public static RMarketMethodInterface_Time createMethod_Time(RMarketTable _market)
{
    RMarketMethod method;
    switch (_market.ApiType)
    {
        case RMarketApiType::Binance:
            method = new RMarketMethod_Binance_Time();

        case RMarketApiType::Bybit:
            method = new RMarketMethod_Bybit_Time();

        default:
            throw error(strFmt("Unsupported api type: %1", enum2Str(_market.ApiType)));
    }
    method.initMarket(_market);
    return method as RMarketMethodInterface_Time;
}

